// 9. ERROR HANDLING MIDDLEWARE
// ============================================================================

// 404 handler
app.use((req, res) => {
  logger.warn({
    message: '404 Not Found',
    path: req.path,
    method: req.method,
    ip: req.ip
  });
  res.status(404).json({
    error: 'Not Found',
    code: 'NOT_FOUND'
  });
});

// Global error handler
app.use((err, req, res, next) => {
  const errorId = Math.random().toString(36).substr(2, 9);

  logger.error({
    errorId,
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip,
    user: req.user?.id
  });

  // Don't expose internal errors to client
  const statusCode = err.statusCode || 500;
  const response = {
    error: err.message || 'Internal server error',
    errorId: config.isProd ? errorId : undefined,
    code: err.code || 'INTERNAL_ERROR'
  };

  // Remove error details in production
  if (config.isProd) {
    response.error = 'Internal server error';
  }

  res.status(statusCode).json(response);
});

// ============================================================================
// 10. GRACEFUL SHUTDOWN
// ============================================================================

const startServer = () => {
  let server;

  if (config.isProd) {
    const options = {
      key: fs.readFileSync(process.env.SSL_KEY_PATH),
      cert: fs.readFileSync(process.env.SSL_CERT_PATH)
    };
    server = https.createServer(options, app);
  } else {
    server = app;
  }

  server.listen(config.port, () => {
    logger.info({
      message: 'Server started',
      port: config.port,
      env: config.env,
      protocol: config.isProd ? 'HTTPS' : 'HTTP'
    });
  });

  // Graceful shutdown
  const gracefulShutdown = (signal) => {
    logger.info({
      message: `${signal} received: graceful shutdown initiated`
    });

    server.close(() => {
      logger.info({ message: 'Server closed' });
      process.exit(0);
    });

    // Force shutdown after 30 seconds
    setTimeout(() => {
      logger.error({
        message: 'Force shutdown initiated'
      });
      process.exit(1);
    }, 30000);
  };

  process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
  process.on('SIGINT', () => gracefulShutdown('SIGINT'));

  // Uncaught exception handler
  process.on('uncaughtException', (err) => {
    logger.error({
      message: 'Uncaught exception',
      error: err.message,
      stack: err.stack
    });
    process.exit(1);
  });

  process.on('unhandledRejection', (reason, promise) => {
    logger.error({
      message: 'Unhandled rejection',
      reason,
      promise: promise.toString()
    });
    process.exit(1);
  });
};

