## Common Attacks & Prevention

### SQL Injection
```javascript
// VULNERABLE
db.query(`SELECT * FROM users WHERE id = ${req.params.id}`);

// SECURE
db.query('SELECT * FROM users WHERE id = $1', [req.params.id]);
```

### XSS (Cross-Site Scripting)
```javascript
// VULNERABLE
res.send(`<h1>${req.query.title}</h1>`);

// SECURE - Using validator escape
query('title').trim().escape()

// Or manually
const safe = req.query.title
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;')
  .replace(/'/g, '&#x27;');
```

### CSRF (Cross-Site Request Forgery)
```javascript
// Use doublecookie pattern or CSRF tokens
const csrf = require('csurf');
const csrfProtection = csrf({ cookie: true });

app.post('/form', csrfProtection, (req, res) => {
  res.render('form', { csrfToken: req.csrfToken() });
});
```

### Path Traversal
```javascript
// VULNERABLE
fs.readFile(path.join(__dirname, req.query.file));

// SECURE
const file = req.query.file.replace(/\.\./g, '');
const safePath = path.resolve('/safe/dir', file);
```

