### Step 3.2: Complete Authentication System

```javascript
const bcrypt = require('bcryptjs');

// Register endpoint
app.post('/auth/register', [
  body('email').isEmail(),
  body('password').isLength({ min: 8 }),
  body('name').trim().notEmpty()
], handleValidationErrors, async (req, res) => {
  const { email, password, name } = req.body;

  // Check if user exists
  let user = await User.findByEmail(email);
  if (user) return res.status(400).json({ error: 'User exists' });

  // Hash password
  const hash = await bcrypt.hash(password, 10);

  // Create user
  user = await User.create({ email, name, password: hash });

  // Generate token
  const token = jwt.sign({ id: user.id }, JWT_SECRET);

  res.json({ token });
});

// Login with bcrypt
app.post('/auth/login', [
  body('email').isEmail(),
  body('password').notEmpty()
], handleValidationErrors, async (req, res) => {
  const { email, password } = req.body;

  const user = await User.findByEmail(email);
  if (!user) return res.status(401).json({ error: 'Invalid credentials' });

  const match = await bcrypt.compare(password, user.password);
  if (!match) return res.status(401).json({ error: 'Invalid credentials' });

  const token = jwt.sign({ id: user.id, role: user.role }, JWT_SECRET);

  res.json({ token });
});
```

### Step 3.3: Role-Based Access Control

```javascript
// Define roles
const ROLES = {
  ADMIN: 'admin',
  USER: 'user',
  GUEST: 'guest'
};

// Authorization middleware
const requireRole = (allowedRoles) => (req, res, next) => {
  if (!allowedRoles.includes(req.user.role)) {
    logger.warn(`Unauthorized: ${req.user.id} tried ${req.path}`);
    return res.status(403).json({ error: 'Forbidden' });
  }
  next();
};

// Admin endpoint
app.get('/admin/users',
  verifyToken,
  requireRole([ROLES.ADMIN]),
  async (req, res) => {
    const users = await User.findAll();
    res.json(users);
  }
);

// User endpoint
app.get('/users/:id',
  verifyToken,
  async (req, res) => {
    const userId = req.params.id;

    // Users can only view their own data
    if (userId !== req.user.id && req.user.role !== ROLES.ADMIN) {
      return res.status(403).json({ error: 'Forbidden' });
    }

    const user = await User.findById(userId);
    res.json(user);
  }
);
```

### Step 3.4: Error Handling

```javascript
// Specific error handlers
class ValidationError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ValidationError';
    this.statusCode = 400;
  }
}

class NotFoundError extends Error {
  constructor(message) {
    super(message);
    this.name = 'NotFoundError';
    this.statusCode = 404;
  }
}

class UnauthorizedError extends Error {
  constructor(message) {
    super(message);
    this.name = 'UnauthorizedError';
    this.statusCode = 401;
  }
}

// Global error handler
app.use((err, req, res, next) => {
  const errorId = Math.random().toString(36).substr(2, 9);

  logger.error({
    errorId,
    message: err.message,
    stack: err.stack,
    path: req.path
  });

  const statusCode = err.statusCode || 500;
  const response = {
    error: process.env.NODE_ENV === 'production' 
      ? 'Internal server error' 
      : err.message,
    errorId
  };

  res.status(statusCode).json(response);
});
