541	      logger.error({
542	        message: 'Force shutdown initiated'
543	      });
544	      process.exit(1);
545	    }, 30000);
546	  };
547	
548	  process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
549	  process.on('SIGINT', () => gracefulShutdown('SIGINT'));
550	
551	  // Uncaught exception handler
552	  process.on('uncaughtException', (err) => {
553	    logger.error({
554	      message: 'Uncaught exception',
555	      error: err.message,
556	      stack: err.stack
557	    });
558	    process.exit(1);
559	  });
